package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"sync"
	"time"

	"golang.org/x/crypto/hkdf"
)

var (
	encKey  []byte
	macKey  []byte
	mu      sync.Mutex
	ledger  [][]byte
	logFile *os.File
)

func deriveKeys(masterKey []byte) ([]byte, []byte, error) {
	// Derive encryption key
	ekdf := hkdf.New(sha256.New, masterKey, []byte("salt-v2"), []byte("encryption-key-v1"))
	ek := make([]byte, 32)
	if _, err := io.ReadFull(ekdf, ek); err != nil {
		return nil, nil, err
	}
	// Derive MAC key
	mkdf := hkdf.New(sha256.New, masterKey, []byte("salt-v2"), []byte("mac-key-v1"))
	mk := make([]byte, 32)
	if _, err := io.ReadFull(mkdf, mk); err != nil {
		return nil, nil, err
	}
	return ek, mk, nil
}

// verifyMAC checks the HMAC-SHA256 tag over the ciphertext
// Following Encrypt-then-MAC: MAC is computed over ciphertext portion
func verifyMAC(macKey, ciphertext, receivedMAC []byte) bool {
	mac := hmac.New(sha256.New, macKey)
	mac.Write(ciphertext)
	expectedMAC := mac.Sum(nil)
	return hmac.Equal(receivedMAC, expectedMAC)
}

// decryptPayload performs authenticated decryption using Encrypt-then-MAC
// Format: [IV (16 bytes)] [Ciphertext (N bytes)] [HMAC-SHA256 (32 bytes)]
func decryptPayload(data []byte) ([]byte, error) {
	blockSize := aes.BlockSize
	macSize := 32
	minLen := blockSize + blockSize + macSize // IV + at least 1 block + MAC

	if len(data) < minLen {
		return nil, fmt.Errorf("payload too short")
	}

	iv := data[:blockSize]
	ciphertextEnd := len(data) - macSize
	ciphertext := data[blockSize:ciphertextEnd]
	receivedMAC := data[ciphertextEnd:]

	if len(ciphertext)%blockSize != 0 {
		return nil, fmt.Errorf("invalid alignment")
	}

	// Verify MAC before decryption (Encrypt-then-MAC pattern)
	// MAC covers the ciphertext to ensure integrity
	if !verifyMAC(macKey, ciphertext, receivedMAC) {
		return nil, fmt.Errorf("authentication failed")
	}

	// MAC verified - safe to decrypt
	block, err := aes.NewCipher(encKey)
	if err != nil {
		return nil, fmt.Errorf("cipher init failed")
	}

	plaintext := make([]byte, len(ciphertext))
	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(plaintext, ciphertext)

	// Remove PKCS7 padding
	padLen := int(plaintext[len(plaintext)-1])
	if padLen < 1 || padLen > blockSize {
		return nil, fmt.Errorf("decryption failed")
	}
	for i := 0; i < padLen; i++ {
		if plaintext[len(plaintext)-1-i] != byte(padLen) {
			return nil, fmt.Errorf("decryption failed")
		}
	}

	return plaintext[:len(plaintext)-padLen], nil
}

func handleTransaction(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	payloadHex := r.Header.Get("X-Encrypted-Payload")
	if payloadHex == "" {
		http.Error(w, "missing payload", http.StatusBadRequest)
		return
	}

	data, err := hex.DecodeString(payloadHex)
	if err != nil {
		http.Error(w, "invalid encoding", http.StatusBadRequest)
		return
	}

	plaintext, err := decryptPayload(data)
	if err != nil {
		// Uniform error response for all decryption failures
		http.Error(w, "processing error", http.StatusBadRequest)
		return
	}

	mu.Lock()
	ledger = append(ledger, plaintext)
	mu.Unlock()

	w.WriteHeader(http.StatusAccepted)
	w.Write([]byte("transaction recorded"))
}

func flushLedger() {
	ticker := time.NewTicker(30 * time.Second)
	for range ticker.C {
		mu.Lock()
		if len(ledger) > 0 {
			for _, entry := range ledger {
				logFile.Write(entry)
				logFile.Write([]byte("\n"))
			}
			ledger = ledger[:0]
		}
		mu.Unlock()
	}
}

func main() {
	masterKey, err := hex.DecodeString(os.Getenv("MASTER_KEY"))
	if err != nil || len(masterKey) != 32 {
		log.Fatal("MASTER_KEY must be 64 hex chars (32 bytes)")
	}

	encKey, macKey, err = deriveKeys(masterKey)
	if err != nil {
		log.Fatal("key derivation failed")
	}

	logFile, err = os.OpenFile("/var/log/transactions.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		log.Fatal("cannot open log file")
	}
	defer logFile.Close()

	go flushLedger()

	http.HandleFunc("/api/v1/transaction", handleTransaction)
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
